using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// AI Controller for the Centipede.
/// Drives the CentipedeIK along a path generated by internal pathfinding.
/// Capable of traversing gaps less than its combined body length.
/// </summary>
public class CentipedeAI : MonoBehaviour
{
    [Header("Behavior")]
    public bool isHostile = false;

    [Header("Targeting")]
    public Transform target; 
    public float arrivalDistance = 2f;
    public float pathRecalculationInterval = 1f;

    [Header("Wandering")]
    public bool isWandering = true;
    public float wanderRadius = 30f;
    public float webPreferenceWeight = 5f;
    public float wanderWaitTime = 2f;
    private Vector2? wanderTarget = null;
    private float wanderTimer = 0f;

    [Header("Path Data")]
    public List<Vector2> path = new List<Vector2>();
    public int currentWaypointIndex = 0;

    [Header("Pathfinding Settings")]
    [Tooltip("Maximum nodes to evaluate before giving up on a path.")]
    public int maxIterations = 500;
    [Tooltip("Movement cost multiplier for web strands. Values < 1 make the AI prefer webs.")]
    public float webCostMultiplier = 0.8f;
    [Tooltip("Buffer for body length reach. 1.0 = 100% of body length.")]
    public float bodyLengthReachFactor = 0.95f;

    [Header("Debug")]
    public LayerMask obstacleLayers;

    private CentipedeIK centipedeIK;
    private float bodyLength = 0f;

    void Awake()
    {
        centipedeIK = GetComponent<CentipedeIK>();
        
        // Default to everything except 'Web' if not set
        if (obstacleLayers == 0)
        {
            obstacleLayers = LayerMask.GetMask("Default");
        }
    }

    void Start()
    {
        CalculateBodyLength();
        
        if (target != null)
        {
            CalculateNewPath(target.position);
        }
        else if (isWandering)
        {
            PickWanderTarget();
        }
        
        StartCoroutine(RecalculatePathPeriodically());
    }

    void CalculateBodyLength()
    {
        if (centipedeIK == null) return;

        bodyLength = 0f;
        Transform prev = centipedeIK.headRb != null ? centipedeIK.headRb.transform : transform;

        if (centipedeIK.bodySegments != null)
        {
            foreach (Transform seg in centipedeIK.bodySegments)
            {
                if (seg == null) continue;
                bodyLength += Vector2.Distance(prev.position, seg.position);
                prev = seg;
            }
        }

        // If body length is still 0 (no segments), use a default reach based on leg extensions if possible
        if (bodyLength <= 0.1f)
        {
            bodyLength = centipedeIK.legExtensionMax * 2f;
        }

        Debug.Log($"[CentipedeAI] Calculated body length: {bodyLength}");
    }

    void FixedUpdate()
    {
        if (centipedeIK == null || !centipedeIK.isAI) return;

        Vector2 headPos = centipedeIK.headRb != null ? (Vector2)centipedeIK.headRb.position : (Vector2)transform.position;
        Vector2 currentGoal;

        if (isHostile && target != null)
        {
            currentGoal = (Vector2)target.position;
        }
        else if (target != null)
        {
            // Even if not hostile, go to explicit target if set
            currentGoal = (Vector2)target.position;
        }
        else if (isWandering)
        {
            if (wanderTarget == null)
            {
                PickWanderTarget();
                if (wanderTarget == null) 
                {
                    centipedeIK.inputDirection = Vector2.zero;
                    return;
                }
            }
            currentGoal = wanderTarget.Value;
        }
        else
        {
            centipedeIK.inputDirection = Vector2.zero;
            return;
        }

        float distToGoal = Vector2.Distance(headPos, currentGoal);

        // 1. Goal Check
        if (distToGoal <= arrivalDistance)
        {
            // Explicitly kill all input once we arrive
            centipedeIK.inputDirection = Vector2.zero;
            
            if (!isHostile && isWandering && target == null)
            {
                wanderTimer += Time.fixedDeltaTime;
                if (wanderTimer >= wanderWaitTime)
                {
                    PickWanderTarget();
                    wanderTimer = 0;
                }
            }
            return;
        }

        // 2. Path Following
        if (path != null && path.Count > 0 && currentWaypointIndex < path.Count)
        {
            Vector2 targetWaypoint = path[currentWaypointIndex];
            Vector2 direction = (targetWaypoint - headPos).normalized;

            // Drive the IK controller
            centipedeIK.inputDirection = direction;

            // Check if we've reached the current waypoint
            // For a centipede, we can be more lenient with waypoint arrival if it's bridging
            float waypointReach = centipedeIK.legExtensionMax * 0.7f;
            if (Vector2.Distance(headPos, targetWaypoint) < waypointReach)
            {
                currentWaypointIndex++;
            }
        }
        else
        {
            // If we run out of path, try to recalculate or just move towards goal directly
            if (distToGoal > centipedeIK.legExtensionMax)
            {
                if (currentWaypointIndex >= (path != null ? path.Count : 0))
                {
                    // If at the end of the path and still far, recalculate
                    CalculateNewPath(currentGoal);
                }
                
                // Fallback attempt to move directly toward goal if path is failing
                if (path == null || path.Count == 0)
                {
                    centipedeIK.inputDirection = (currentGoal - headPos).normalized;
                }
            }
            else
            {
                centipedeIK.inputDirection = (currentGoal - headPos).normalized;
            }
        }
    }

    void PickWanderTarget()
    {
        bool showDebug = GameSetup.Instance != null && GameSetup.Instance.showAIDebug;
        if (GlobalAttachmentManager.TotalPoints == 0)
        {
            if (showDebug) Debug.LogWarning("[CentipedeAI] Still waiting for GlobalAttachmentManager points...");
            return;
        }

        Vector2 headPos = centipedeIK.headRb != null ? (Vector2)centipedeIK.headRb.position : (Vector2)transform.position;
        
        // Weighted random selection
        float totalWeight = 0;
        List<(Vector2 pos, float weight)> weightedPoints = new List<(Vector2, float)>();
        
        foreach (var point in GlobalAttachmentManager.AllPoints())
        {
            float dist = Vector2.Distance(headPos, point.Position);
            if (dist > wanderRadius || dist < arrivalDistance) continue;

            float weight = 1.0f;
            if (point.webTransform != null) weight = webPreferenceWeight;
            
            // Favor points that are further away to encourage movement
            float distRatio = dist / wanderRadius;
            weight *= (distRatio * distRatio); 

            weightedPoints.Add((point.Position, weight));
            totalWeight += weight;
        }

        if (weightedPoints.Count == 0)
        {
            // Fallback: Pick any point in range if no weighted points found
            var allPoints = GlobalAttachmentManager.GetPointsInRange(headPos, wanderRadius);
            if (allPoints.Count > 0)
            {
                wanderTarget = allPoints[Random.Range(0, allPoints.Count)].Position;
                CalculateNewPath(wanderTarget.Value);
                if (showDebug) Debug.Log($"[CentipedeAI] Picking random wander target: {wanderTarget.Value}");
            }
            else
            {
                if (showDebug) Debug.LogWarning("[CentipedeAI] No points found in range picking random point in radius as target.");
                // Hard-random fallback in case no attachment points were found in range
                Vector2 randomOffset = Random.insideUnitCircle * wanderRadius;
                wanderTarget = headPos + randomOffset;
                CalculateNewPath(wanderTarget.Value);
            }
            return;
        }

        float randomVal = Random.value * totalWeight;
        float currentWeightSum = 0;
        foreach (var wp in weightedPoints)
        {
            currentWeightSum += wp.weight;
            if (randomVal <= currentWeightSum)
            {
                wanderTarget = wp.pos;
                CalculateNewPath(wanderTarget.Value);
                if (showDebug) Debug.Log($"[CentipedeAI] Picked weighted wander target: {wanderTarget.Value}");
                break;
            }
        }
    }

    public void CalculateNewPath(Vector2 goalPos)
    {
        Vector2 startPos = centipedeIK.headRb != null ? (Vector2)centipedeIK.headRb.position : (Vector2)transform.position;
        path = InternalCalculatePath(startPos, goalPos);
        currentWaypointIndex = 0;

        bool showDebug = GameSetup.Instance != null && GameSetup.Instance.showAIDebug;

        if (path == null || path.Count == 0)
        {
            if (showDebug) Debug.LogWarning($"[CentipedeAI] Pathfinding failed to: {goalPos}");
            // Optional: immediately pick a new wander target in the next frame
            if (isWandering && target == null) wanderTarget = null;
        }
        else
        {
            if (showDebug) Debug.Log($"[CentipedeAI] Path found with {path.Count} waypoints.");
        }
    }

    private List<Vector2> InternalCalculatePath(Vector2 startPosition, Vector2 targetPosition)
    {
        if (centipedeIK == null) return new List<Vector2>();

        // 1. Initialize A* structures
        List<PathNode> openList = new List<PathNode>();
        HashSet<Vector2> closedSet = new HashSet<Vector2>();

        // Reach is the body length factor
        // We use body length as the maximum bridging distance
        float reach = bodyLength * bodyLengthReachFactor;
        if (reach <= 0) reach = 5f; // Fallback

        // Find initial normal for start position (closest surface normal)
        Vector2 startNormal = Vector2.up;
        RaycastHit2D hit = Physics2D.Raycast(startPosition, -centipedeIK.headRb.transform.up, 2f, obstacleLayers);
        if (hit.collider != null) startNormal = hit.normal;

        PathNode startNode = new PathNode(startPosition, startNormal, null, 0, Vector2.Distance(startPosition, targetPosition));
        openList.Add(startNode);

        int iterations = 0;
        while (openList.Count > 0)
        {
            iterations++;
            if (iterations > maxIterations) break;

            int bestIdx = 0;
            for (int i = 1; i < openList.Count; i++)
            {
                if (openList[i].F < openList[bestIdx].F) bestIdx = i;
            }

            PathNode currentNode = openList[bestIdx];

            // Goal Check
            if (Vector2.Distance(currentNode.Position, targetPosition) <= centipedeIK.legExtensionMax)
            {
                List<Vector2> foundPath = ReconstructPath(currentNode);
                foundPath.Add(targetPosition); 
                return foundPath;
            }

            openList.RemoveAt(bestIdx);
            closedSet.Add(currentNode.Position);

            // Neighbor Expansion using GlobalAttachmentManager
            List<GlobalAttachmentPoint> pointsNear = GlobalAttachmentManager.GetPointsInRange(currentNode.Position, reach);
            
            foreach (var point in pointsNear)
            {
                if (closedSet.Contains(point.Position)) continue;

                float stepDist = Vector2.Distance(currentNode.Position, point.Position);
                
                // --- OBSTRUCTION CHECK ---
                // We use a Linecast shifted slightly away from the surfaces to check for blocking geometry.
                Vector2 rayStart = currentNode.Position + currentNode.Normal * 0.2f;
                Vector2 rayEnd = point.Position + point.normal * 0.2f;
                
                // We also check with a small width to ensure the centipede body can pass
                RaycastHit2D obstruction = Physics2D.CircleCast(rayStart, 0.2f, (rayEnd - rayStart).normalized, Vector2.Distance(rayStart, rayEnd), obstacleLayers);

                if (obstruction.collider != null)
                {
                    continue; // Path blocked by solid geometry!
                }

                // Weighting logic
                if (point.webTransform != null) stepDist *= webCostMultiplier;
                
                float gCost = currentNode.G + stepDist;
                float hCost = Vector2.Distance(point.Position, targetPosition);

                PathNode existingNode = null;
                foreach(var n in openList)
                {
                    if (n.Position == point.Position)
                    {
                        existingNode = n;
                        break;
                    }
                }

                if (existingNode != null)
                {
                    if (gCost < existingNode.G)
                    {
                        existingNode.Parent = currentNode;
                        existingNode.G = gCost;
                    }
                }
                else
                {
                    openList.Add(new PathNode(point.Position, point.normal, currentNode, gCost, hCost));
                }
            }
        }

        return new List<Vector2>();
    }

    private List<Vector2> ReconstructPath(PathNode endNode)
    {
        List<Vector2> foundPath = new List<Vector2>();
        PathNode curr = endNode;
        while (curr != null)
        {
            foundPath.Add(curr.Position);
            curr = curr.Parent;
        }
        foundPath.Reverse();
        return foundPath;
    }

    IEnumerator RecalculatePathPeriodically()
    {
        while (true)
        {
            yield return new WaitForSeconds(pathRecalculationInterval);
            if (target != null)
            {
                CalculateNewPath(target.position);
            }
            else if (isWandering && wanderTarget != null)
            {
                CalculateNewPath(wanderTarget.Value);
            }
        }
    }

    private class PathNode
    {
        public Vector2 Position;
        public Vector2 Normal;
        public PathNode Parent;
        public float G;
        public float H;
        public float F => G + H;

        public PathNode(Vector2 pos, Vector2 normal, PathNode parent, float g, float h)
        {
            Position = pos;
            Normal = normal;
            Parent = parent;
            G = g;
            H = h;
        }
    }

    void OnDrawGizmos()
    {
        if (GameSetup.Instance == null || !GameSetup.Instance.showAIDebug) return;

        if (path != null && path.Count > 0)
        {
            Gizmos.color = Color.magenta;
            for (int i = currentWaypointIndex; i < path.Count - 1; i++)
            {
                Gizmos.DrawLine(path[i], path[i + 1]);
                Gizmos.DrawWireSphere(path[i], 0.3f);
            }
        }

        if (wanderTarget != null)
        {
            Gizmos.color = Color.yellow;
            Gizmos.DrawWireSphere(wanderTarget.Value, 0.6f);
        }
        
        // Visualize reach
        if (centipedeIK != null)
        {
            Gizmos.color = new Color(1, 0, 1, 0.1f);
            Vector2 headPos = centipedeIK.headRb != null ? (Vector2)centipedeIK.headRb.position : (Vector2)transform.position;
            Gizmos.DrawWireSphere(headPos, bodyLength * bodyLengthReachFactor);
        }
    }
}
